suppressPackageStartupMessages(library(data.table));a<-grep('^--file=',commandArgs(),value=T);setwd(dirname(dirname(normalizePath(sub('^--file=','',a[1])))))
d<-readRDS('data/audited_raw.rds');mm<-rbindlist(d$meta,fill=T)[excluded==FALSE];mp<-fread('tables/feature_mapping.csv');cat0<-fread('tables/feature_catalog.csv');ev<-rbindlist(lapply(cat0$feature_id,function(fid){rec<-mp[feature_id==fid];v<-rep(NA_real_,nrow(mm));support<-0;for(k in seq_len(nrow(rec))){b<-rec$batch[k];ii<-which(mm$batch==b);z<-d$raw[[b]][mm$cell_id[ii],rec$source_column[k]];v[ii]<-z;support<-support+as.integer(any(z>0))};rates<-tapply(!is.na(v)&v>0,mm$group,mean);data.table(feature_id=fid,n_support_series=support,max_label_detection=max(rates),kept=length(unique(rec$batch))==2||(support>=2&&max(rates)>=.5))}));stopifnot(identical(ev$kept,cat0$keep));fwrite(merge(cat0,ev,by='feature_id'),'tables/feature_screening_complete.csv')
fwrite(rbindlist(lapply(names(d$var),function(b){v<-d$var[[b]];data.table(batch=b,n_source_features=nrow(v),duplicate_source_names=sum(duplicated(v$`_index`)),missing_mz=sum(!is.finite(v$mz_center)),missing_annotation=sum(is.na(v$metabolite)|!nzchar(v$metabolite)))})),'tables/feature_source_identity_audit.csv')
# Refit affine parameters on 80% of each anchor/batch, apply to unchanged full matrix.
expr<-parse('scripts/01_integrate.R');for(e in expr)if(is.call(e)&&identical(e[[1]],as.name('<-'))&&is.symbol(e[[2]])&&as.character(e[[2]])%in%c('combat_affine','apply_affine'))eval(e)
COMBAT_TOL<-1e-4;z<-readRDS('data/integration_candidates.rds');X<-z$before;m<-z$meta;out<-list();set.seed(91)
for(rep in 1:3){masks<-list();for(day in c('D0','D14')){mask<-rep(F,nrow(m));for(b in c('B1','B2')){ix<-which(m$batch==b&m$day==day);mask[sample(ix,floor(.8*length(ix)))]<-T};masks[[day]]<-mask};b0<-apply_affine(X,m$batch,combat_affine(X,m$batch,masks$D0));b14<-apply_affine(b0,m$batch,combat_affine(b0,m$batch,masks$D14));w<-suppressWarnings(as.numeric(sub('D','',m$day)))/14;w[is.na(w)]<-0;zz<-b0+(b14-b0)*w;out[[rep]]<-data.table(repeat_id=rep,RMSE=sqrt(mean((zz-z$D0_D14)^2)),global_pearson=cor(as.vector(zz),as.vector(z$D0_D14)),max_abs_difference=max(abs(zz-z$D0_D14)))};fwrite(rbindlist(out),'tables/anchor_parameter_subsampling_robustness.csv');print(rbindlist(out))
